using Unity.Burst;
using Unity.Collections;
using Unity.Jobs;

public interface ISpeedRule
{
    float Speed(float distance, float baseSpeed);
}

public struct Flee : ISpeedRule
{
    public float Speed(float distance, float baseSpeed) => baseSpeed * 2f;
}

[BurstCompile]
struct MoveJob<TRule> : IJobParallelFor where TRule : struct, ISpeedRule
{
    public TRule rule;                               // known at compile time
    [ReadOnly] public NativeArray<float> distance;
    public NativeArray<float> speed;
    public float baseSpeed;

    public void Execute(int i) => speed[i] = rule.Speed(distance[i], baseSpeed);
}

public static class Steering
{
    public static JobHandle Schedule(NativeArray<float> distance, NativeArray<float> speed, float baseSpeed)
    {
        // a concrete type here, not a generic method: Burst finds MoveJob<Flee> in a build
        return new MoveJob<Flee> { distance = distance, speed = speed, baseSpeed = baseSpeed }
            .Schedule(distance.Length, 64);
    }
}

