using Unity.Burst;
using Unity.Jobs;
using Unity.Mathematics;
using UnityEngine;
using UnityEngine.Jobs;

// was: a Spinner component with its own Update on each of 10 000 objects
public class SpinManager : MonoBehaviour
{
    public Transform[] items;        // all at the scene root
    public float degreesPerSecond = 90f;

    TransformAccessArray transforms;
    JobHandle handle;

    void Awake()
    {
        transforms = new TransformAccessArray(items);
    }

    void Update()
    {
        // Time is main-thread API: compute the rotation here, pass it in
        var delta = quaternion.RotateY(math.radians(degreesPerSecond * Time.deltaTime));
        handle = new SpinJob { delta = delta }.Schedule(transforms);
        JobHandle.ScheduleBatchedJobs();
    }

    void LateUpdate() => handle.Complete();

    void OnDestroy()
    {
        handle.Complete();           // the job may still be using the transforms
        transforms.Dispose();
    }
}

[BurstCompile]
struct SpinJob : IJobParallelForTransform
{
    public quaternion delta;

    public void Execute(int index, TransformAccess transform)
    {
        transform.localRotation = math.mul(transform.localRotation, delta);
    }
}

